namespace EPejabat\Core;
final class RegistrationMaster {
 public static function ready(\PDO $p):bool {return (bool)Database::query($p,"SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='registration_requests' AND COLUMN_NAME='email_type'")->fetchColumn();}
 public static function phone(string $value):string {
  if(trim($value)==='')return '';
  if(preg_match('/[^0-9+ ()-]/',$value))throw new \InvalidArgumentException('Nombor telefon tidak sah.');
  $v=preg_replace('/[ ()-]/','',$value);if(str_starts_with($v,'00'))$v='+'.substr($v,2);if(str_starts_with($v,'0'))$v='+60'.substr($v,1);elseif(str_starts_with($v,'60'))$v='+'.$v;
  if(!preg_match('/\A\+60[1-9][0-9]{7,9}\z/',$v))throw new \InvalidArgumentException('Gunakan nombor Malaysia yang sah.');return $v;
 }
 public static function emailType(\PDO $p,string $email):string {
  $email=Core::email($email);$domain=substr(strrchr($email,'@'),1);$raw=Database::query($p,"SELECT setting_value FROM system_settings WHERE setting_key='official_email_domains'")->fetchColumn();$domains=$raw!==false?explode(',',(string)$raw):['moh.gov.my'];
  return in_array($domain,array_map('trim',$domains),true)?'official':'personal';
 }
 public static function employment(\PDO $p,array $d):array {
  $profession=MasterData::validate($p,Core::id($d['profession_id']??null,true),'profession');$position=MasterData::validate($p,Core::id($d['position_id']??null,true),'position');$grade=MasterData::validate($p,Core::id($d['grade_id']??null,true),'grade');
  if($grade!==null&&($profession===null||$position===null||!Database::query($p,'SELECT 1 FROM master_scheme_grades WHERE profession_id=? AND position_id=? AND grade_id=? AND is_active=1 AND (effective_from IS NULL OR effective_from<=UTC_DATE())',[$profession,$position,$grade])->fetchColumn()))throw new \InvalidArgumentException('Padanan profesion, skim dan gred belum disahkan.');return [$profession,$position,$grade];
 }
 public static function organisations(\PDO $p,?int $parent,string $search=''):array {
  $search=Core::text($search,100,false);$args=[];$where='o.is_active=1';if($parent!==null){$where.=' AND o.parent_id=?';$args[]=$parent;}else $where.=" AND o.type='state'";
  if($search!==''){if(self::profileReady($p)){$where.=' AND (o.name LIKE ? OR EXISTS(SELECT 1 FROM organisation_search_aliases a WHERE a.organisation_id=o.id AND a.alias LIKE ?))';$args[]='%'.$search.'%';$args[]='%'.$search.'%';}else{$where.=' AND o.name LIKE ?';$args[]='%'.$search.'%';}}
  return Database::query($p,'SELECT o.id,o.name,o.type,o.parent_id,o.address,o.phone FROM organisations o WHERE '.$where.' ORDER BY o.name LIMIT 200',$args)->fetchAll();
 }
 public static function masters(\PDO $p,string $category,?int $profession=null,?int $position=null):array {
  if(!in_array($category,['profession','position','grade'],true))throw new \InvalidArgumentException('Kategori tidak sah.');
  if($category==='profession')return Database::query($p,"SELECT id,name FROM master_data WHERE category='profession' AND is_active=1 ORDER BY name")->fetchAll();
  if(!$profession)return [];if($category==='grade'&&!$position)return [];
  $column=$category==='position'?'position_id':'grade_id';$where=$category==='grade'?' AND g.position_id=?':'';$args=[$profession];if($category==='grade')$args[]=$position;
  return Database::query($p,"SELECT DISTINCT m.id,m.name FROM master_scheme_grades g JOIN master_data m ON m.id=g.$column WHERE g.profession_id=? AND g.is_active=1 AND m.is_active=1 AND (g.effective_from IS NULL OR g.effective_from<=UTC_DATE())".$where.' ORDER BY m.name',$args)->fetchAll();
 }
 public static function contactSave(\PDO $p,int $actor,int $staff,array $d):void {
  $profile=Staff::get($p,$actor,$staff);$self=(int)($profile['user_id']??0)===$actor;$org=$profile['organisation_id']===null?null:(int)$profile['organisation_id'];if(!$self)Authorization::require($p,$actor,'core.staff.manage',$org);
  $alt=self::phone(Core::text($d['alternative_phone']??'',30,false));$wa=self::phone(Core::text($d['whatsapp_number']??'',30,false));$consent=($d['whatsapp_consent']??'0')==='1';$visibility=$d['visibility']??'private';if(!in_array($visibility,['private','organisation'],true))throw new \InvalidArgumentException('Privacy tidak sah.');
  // Only the staff member may grant disclosure consent; admins cannot opt someone in.
  if(!$self&&($consent||$visibility!=='private'))throw new \RuntimeException('Persetujuan staf diperlukan.');
  Core::tx($p,function()use($p,$actor,$staff,$alt,$wa,$consent,$visibility,$org){Database::query($p,'INSERT INTO staff_contact_preferences(staff_identity_id,alternative_phone,whatsapp_number,whatsapp_consent,visibility) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE alternative_phone=VALUES(alternative_phone),whatsapp_number=VALUES(whatsapp_number),whatsapp_consent=VALUES(whatsapp_consent),visibility=VALUES(visibility)',[$staff,$alt?:null,$wa?:null,$consent?1:0,$visibility]);Audit::record($p,'staff.contact_preferences',$actor,$org,(string)$staff,'core',null,null,['consent'=>$consent,'visibility'=>$visibility]);});
 }
 public static function contact(\PDO $p,int $actor,int $staff):array {
  $r=Staff::get($p,$actor,$staff);$self=(int)($r['user_id']??0)===$actor;$org=$r['organisation_id']===null?null:(int)$r['organisation_id'];$c=Database::query($p,'SELECT * FROM staff_contact_preferences WHERE staff_identity_id=?',[$staff])->fetch();if(!$c)return [];
