  Core::tx($p,function()use($p,$actor,$id,$reason,$postcode,$district,$direct,$wa,$ext){$old=Database::query($p,'SELECT * FROM organisation_directory_details WHERE organisation_id=? FOR UPDATE',[$id])->fetch();Database::query($p,"INSERT INTO organisation_directory_details(organisation_id,postcode,district,direct_phone,extension,official_whatsapp,verification_status) VALUES(?,?,?,?,?,?,'ADMIN_REVIEW_REQUIRED') ON DUPLICATE KEY UPDATE postcode=VALUES(postcode),district=VALUES(district),direct_phone=VALUES(direct_phone),extension=VALUES(extension),official_whatsapp=VALUES(official_whatsapp),verification_status='ADMIN_REVIEW_REQUIRED'",[$id,$postcode?:null,$district?:null,$direct?:null,$ext?:null,$wa?:null]);Audit::record($p,'organisation.directory_contact_updated',$actor,$id,(string)$id,'core',$reason,$old?:null,['postcode'=>$postcode,'district'=>$district,'direct_phone'=>$direct,'extension'=>$ext,'official_whatsapp'=>$wa]);});
