 public static function missingOrganisation(\PDO $p,int $actor,int $parent,string $name):int {
  $profile=Database::query($p,'SELECT organisation_id FROM staff_profiles WHERE staff_identity_id=(SELECT staff_identity_id FROM users WHERE id=? AND is_active=1)',[$actor])->fetch();if(!$profile||!Database::query($p,'SELECT 1 FROM organisation_hierarchy WHERE ancestor_id=? AND descendant_id=?',[$parent,$profile['organisation_id']])->fetchColumn())throw new \RuntimeException('Permohonan mesti dalam hierarchy organisasi anda.');$name=Core::text($name);
  return Core::tx($p,function()use($p,$actor,$parent,$name){if(Database::query($p,'SELECT 1 FROM organisations WHERE parent_id=? AND name=?',[$parent,$name])->fetchColumn()||Database::query($p,"SELECT 1 FROM organisation_requests WHERE parent_id=? AND proposed_name=? AND status='PENDING_VERIFICATION'",[$parent,$name])->fetchColumn())throw new \InvalidArgumentException('Organisasi/permohonan sudah wujud.');Database::query($p,'INSERT INTO organisation_requests(parent_id,requested_by,proposed_name) VALUES(?,?,?)',[$parent,$actor,$name]);$id=(int)$p->lastInsertId();Audit::record($p,'organisation.requested',$actor,$parent,(string)$id);return $id;});
 }
