 public static function profileReady(\PDO $p):bool {return (bool)Database::query($p,"SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='staff_profile_extensions'")->fetchColumn();}
 public static function sourceUrl(string $value):string {$v=Core::text($value,1000);$u=parse_url($v);if(($u['scheme']??'')!=='https'||isset($u['user'])||isset($u['pass'])||!in_array($u['host']??'',['docs.jpa.gov.my','pharmacy.moh.gov.my','jknjohor.moh.gov.my','www.moh.gov.my','jknkelantan.moh.gov.my','www.spa.gov.my','spa.gov.my','www.nsr.org.my','nsr.org.my','www.mmc.gov.my','mmc.gov.my'],true))throw new \InvalidArgumentException('Rujukan rasmi HTTPS diperlukan.');return $v;}
 private static function owner(\PDO $p,int $actor,int $staff):array {$r=Staff::get($p,$actor,$staff);if((int)($r['user_id']??0)!==$actor||!Database::query($p,'SELECT 1 FROM users WHERE id=? AND is_active=1',[$actor])->fetchColumn())throw new \RuntimeException('Hanya pemilik profil boleh menghantar perubahan ini.');return $r;}
 public static function extendedProfile(\PDO $p,int $actor,int $staff):array {
