 public static function addressFields(array $d,string $prefix=''):array {$out=[];foreach(['line1','line2','street','postcode','city','state'] as $k){$v=Core::text($d[$prefix.$k]??'',($k==='postcode'?5:($k==='line1'?1000:190)),false);if($k==='postcode'&&$v!==''&&!preg_match('/\A[0-9]{5}\z/',$v))throw new \InvalidArgumentException('Poskod mesti tepat lima digit.');$out[$k]=$v!==''?$v:null;}return $out;}
