  foreach(['substantive_position','acting_grade','kup_grade'] as $k)$values[$k]=Core::text($d[$k]??'',190,false);$level=$d['specialist_level']??'NONE';$gradeCode=$grade?Database::query($p,'SELECT code FROM master_data WHERE id=?',[$grade])->fetchColumn():null;if(in_array($gradeCode,['UD15','UG15'],true)&&$level==='NONE')throw new \InvalidArgumentException('Gred Pakar memerlukan permohonan status kepakaran.');if(!in_array($level,['NONE','SPECIALIST','CONSULTANT'],true)||$level!=='NONE'&&!$values['speciality_id'])throw new \InvalidArgumentException('Tahap kepakaran memerlukan bidang yang sah.');$values['specialist_level']=$level;
