 public static function emailContactRequest(\PDO $p,int $actor,string $email):void {
  $u=Database::query($p,'SELECT staff_identity_id FROM users WHERE id=? AND is_active=1',[$actor])->fetch();if(!$u)throw new \RuntimeException('Login diperlukan.');$email=Core::email($email);Accounts::throttle($p,'contact_email','actor:'.$actor);$type=self::emailType($p,$email);$token=bin2hex(random_bytes(32));$expires=gmdate('Y-m-d H:i:s',time()+3600);
  Core::tx($p,function()use($p,$actor,$u,$email,$type,$token,$expires){if(Database::query($p,'SELECT 1 FROM users WHERE email=? AND staff_identity_id<>?',[$email,$u['staff_identity_id']])->fetchColumn()||Database::query($p,'SELECT 1 FROM staff_profiles WHERE official_email=? AND staff_identity_id<>?',[$email,$u['staff_identity_id']])->fetchColumn())throw new \InvalidArgumentException('E-mel tidak boleh digunakan.');$existing=Database::query($p,'SELECT * FROM staff_email_contacts WHERE email=? FOR UPDATE',[$email])->fetch();if($existing){if($existing['status']!=='PENDING_EMAIL_VERIFICATION'&&((int)$existing['staff_identity_id']!==(int)$u['staff_identity_id']||$existing['status']!=='REJECTED'))throw new \RuntimeException('Contact telah dipautkan; perubahan melalui approval/recovery.');Database::query($p,"UPDATE staff_email_contacts SET staff_identity_id=?,email_type=?,token_hash=?,expires_at=?,verified_at=NULL,approved_by=NULL,status='PENDING_EMAIL_VERIFICATION',is_notification_primary=0 WHERE id=?",[$u['staff_identity_id'],$type,hash('sha256',$token),$expires,$existing['id']]);}else Database::query($p,'INSERT INTO staff_email_contacts(staff_identity_id,email,email_type,token_hash,expires_at) VALUES(?,?,?,?,?)',[$u['staff_identity_id'],$email,$type,hash('sha256',$token),$expires]);Notifications::enqueue($p,$email,'activation',['url'=>Accounts::origin().'/profile?contact_token='.$token,'expires_at'=>$expires,'context'=>'profile_email_contact','email_type'=>$type]);Audit::record($p,'profile.email_contact_requested',$actor,null,(string)$u['staff_identity_id'],'core',null,null,['email_type'=>$type]);});
