 }
 public static function emailContactReview(\PDO $p,int $actor,int $id,string $decision,string $reason):void {
  if(!in_array($decision,['APPROVED','REJECTED'],true))throw new \InvalidArgumentException('Keputusan tidak sah.');$reason=Core::text($reason,500);Core::tx($p,function()use($p,$actor,$id,$decision,$reason){$v=Database::query($p,'SELECT c.*,s.organisation_id,u.id AS owner FROM staff_email_contacts c JOIN staff_profiles s ON s.staff_identity_id=c.staff_identity_id JOIN users u ON u.staff_identity_id=c.staff_identity_id WHERE c.id=? FOR UPDATE',[$id])->fetch();if(!$v||$v['status']!=='PENDING_ADMIN_APPROVAL'||!$v['verified_at'])throw new \RuntimeException('Pemilikan e-mel/semakan tidak sah.');if(!Database::query($p,'SELECT 1 FROM users WHERE id=? AND is_active=1',[$actor])->fetchColumn())throw new \RuntimeException('Admin aktif diperlukan.');Authorization::require($p,$actor,'core.registrations.review',$v['organisation_id']===null?null:(int)$v['organisation_id']);Database::query($p,'UPDATE staff_email_contacts SET status=?,approved_by=? WHERE id=?',[$decision,$actor,$id]);Audit::record($p,'profile.email_contact_reviewed',$actor,(int)$v['organisation_id'],(string)$v['staff_identity_id'],'core',$reason,null,['contact_id'=>$id,'status'=>$decision,'self_approval'=>(int)$v['owner']===$actor]);});
 }
 public static function notificationContact(\PDO $p,int $actor,int $id):void {$u=Database::query($p,'SELECT staff_identity_id FROM users WHERE id=? AND is_active=1',[$actor])->fetchColumn();Core::tx($p,function()use($p,$actor,$id,$u){Database::query($p,'SELECT id FROM users WHERE id=? FOR UPDATE',[$actor]);if(!Database::query($p,"SELECT 1 FROM staff_email_contacts WHERE id=? AND staff_identity_id=? AND status='APPROVED' AND verified_at IS NOT NULL",[$id,$u])->fetchColumn())throw new \RuntimeException('Contact belum disahkan/diluluskan.');Database::query($p,'UPDATE staff_email_contacts SET is_notification_primary=0 WHERE staff_identity_id=?',[$u]);Database::query($p,'UPDATE staff_email_contacts SET is_notification_primary=1 WHERE id=?',[$id]);Audit::record($p,'profile.notification_contact_changed',$actor,null,(string)$u,'core',null,null,['contact_id'=>$id]);});}

 public static function verifyDirectory(\PDO $p,int $actor,int $id,array $d):void {
  Authorization::require($p,$actor,'core.organisations.manage',$id);$source=self::sourceUrl($d['source']??'');$reason=Core::text($d['reason']??'',500);$expected=Core::text($d['expected_hash']??'',64);$address=Core::text($d['address']??'',1000,false);$postcode=Core::text($d['postcode']??'',5,false);if($postcode!==''&&!preg_match('/\A[0-9]{5}\z/',$postcode))throw new \InvalidArgumentException('Poskod tidak sah.');$city=Core::text($d['city']??'',190,false);$street=Core::text($d['street']??'',190,false);$state=Core::text($d['address_state']??'',190,false);$district=Core::text($d['district']??'',100,false);$phone=self::phone(Core::text($d['phone']??'',30,false));
  Core::tx($p,function()use($p,$actor,$id,$source,$reason,$address,$postcode,$city,$street,$state,$district,$phone,$expected){$before=Database::query($p,'SELECT o.id,o.address,o.phone,d.postcode,d.city,d.street,d.address_state,d.district,d.source_reference,d.verification_status FROM organisations o LEFT JOIN organisation_directory_details d ON d.organisation_id=o.id WHERE o.id=? FOR UPDATE',[$id])->fetch();if(!$before)throw new \InvalidArgumentException('Organisasi tidak wujud.');if(!hash_equals(hash('sha256',json_encode($before,JSON_THROW_ON_ERROR)),$expected))throw new \RuntimeException('Directory berubah atau preview belum dipilih; muat semula sebelum kemas kini.');Database::query($p,'UPDATE organisations SET address=?,phone=? WHERE id=?',[$address?:null,$phone?:null,$id]);Database::query($p,"INSERT INTO organisation_directory_details(organisation_id,postcode,district,source_reference,verified_at,verification_status,city,street,address_state,address_verified_by) VALUES(?,?,?,?,UTC_DATE(),'ADMIN_CONFIRMED_SOURCE',?,?,?,?) ON DUPLICATE KEY UPDATE postcode=VALUES(postcode),district=VALUES(district),source_reference=VALUES(source_reference),verified_at=VALUES(verified_at),verification_status=VALUES(verification_status),city=VALUES(city),street=VALUES(street),address_state=VALUES(address_state),address_verified_by=VALUES(address_verified_by)",[$id,$postcode?:null,$district?:null,$source,$city?:null,$street?:null,$state?:null,$actor]);Audit::record($p,'organisation.directory_verified',$actor,$id,(string)$id,'core',$reason,$before,['address'=>$address?:null,'phone'=>$phone?:null,'source'=>$source]);});
 }

